const $=id=>document.getElementById(id), W=1160,H=1720,G={x:24,y:305,w:1112,h:1100};
const images=new Map();const assets={};let state,stage='entry',step=1,selected=0,picks=new Set(),entryPicks=new Set(),historyStack=[],redoStack=[],swapFrom=null,picking=false,dragFrom=null,saveTimer,toastTimer,uploadMode='multi',isGuest=false,questionId=null,answerVisible=false;
const clone=x=>JSON.parse(JSON.stringify(x));const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);const blank=()=>({id:uid(),type:'text',text:'',bg:'#f8f8f8',fg:'#000000',size:1,align:'left',locked:false,zoom:1,px:.5,py:.5});
function newState(){return {v:1,topic:'design',cols:3,rows:3,cells:Array.from({length:9},blank),shelf:[],line:'auto',lineWidth:5,precision:0,mode:'open',answer:[],whole:null,gray:false};}
