function img(src){if(!images.has(src)){const i=new Image();i.onload=()=>draw();i.onerror=()=>toast('有一张图片未能读取，请重新上传。');i.src=src;images.set(src,i);}return images.get(src);}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400);}
function textLines(ctx,t,x,y,w,h,kind,size=1,align='left'){let fs=(kind==='number'?Math.min(h*.32,w*.5):Math.min(w*.54,h*.54))*size;const para=String(t).split('\n');function wrap(f){ctx.font=`${kind==='number'?700:500} ${f}px Arial, "Microsoft YaHei", sans-serif`;const lines=[];for(const p of para){let line='';for(const ch of p){if(line&&ctx.measureText(line+ch).width>w-10){lines.push(line);line=ch;}else line+=ch;}lines.push(line);}return lines;}
let lines=wrap(fs);while(fs>12&&(lines.length*fs*.82>h-12||lines.some(l=>ctx.measureText(l).width>w-10))){fs*=.96;lines=wrap(fs);}ctx.font=`${kind==='number'?700:500} ${fs}px Arial, "Microsoft YaHei", sans-serif`;ctx.textBaseline='top';ctx.textAlign=align==='center'?'center':'left';let yy=kind==='number'?(y+h/2-lines.length*fs*.84/2-fs*.07):y+6-fs*.08;for(const l of lines){ctx.fillText(l,align==='center'?x+w/2:x+5,yy);yy+=fs*.82;}}
function cover(ctx,im,x,y,w,h,z=1,px=.5,py=.5,rect=null){if(!im.complete||!im.naturalWidth)return;let r=rect||{x:0,y:0,w:im.naturalWidth,h:im.naturalHeight};const a=w/h;let sw=r.w,sh=r.h;if(sw/sh>a)sw=sh*a;else sh=sw/a;sw/=z;sh/=z;const sx=r.x+(r.w-sw)*px,sy=r.y+(r.h-sh)*py;ctx.drawImage(im,sx,sy,sw,sh,x,y,w,h);}
function check(ctx,x,y,sz,lineWidth=5){ctx.save();ctx.beginPath();ctx.arc(x+sz/2,y+sz/2,sz/2-2,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle='#000';ctx.lineWidth=lineWidth;ctx.stroke();ctx.beginPath();ctx.moveTo(x+sz*.21,y+sz*.59);ctx.lineTo(x+sz*.41,y+sz*.78);ctx.lineTo(x+sz*.77,y+sz*.22);ctx.lineWidth=6;ctx.stroke();ctx.restore();}
function entryState(){const s=newState();['des\nign','360','设计\n节','360','des\nign','fest\nival','2026','11.\n26-','11.\n29'].forEach((t,i)=>Object.assign(s.cells[i],{text:t,type:isNumeric(t)?'number':'text',align:isHeroNumber(t)?'left':isNumeric(t)?'center':'left'}));return s;}
function drawTo(ctx,s,marks){ctx.fillStyle='#f8f8f8';ctx.fillRect(0,0,W,H);ctx.fillStyle='#000';ctx.textAlign='left';ctx.textBaseline='top';ctx.letterSpacing='0px';ctx.font='700 72px "D360Bold", Arial, sans-serif';ctx.fillText('Select all squares with',23,43);const right=1110,y=53;ctx.textAlign='right';ctx.font='700 72px "D360Bold", Arial, sans-serif';ctx.fillText(String(s.rows),right,y);const rowWidth=ctx.measureText(String(s.rows)).width;ctx.font='400 72px "D360Roman", Arial, sans-serif';ctx.fillText('x',right-rowWidth,y);const xWidth=ctx.measureText('x').width;ctx.font='700 72px "D360Bold", Arial, sans-serif';ctx.fillText(String(s.cols),right-rowWidth-xWidth,y);ctx.textAlign='left';let ts=72;const topicChinese=/[\u3400-\u9fff]/.test(s.topic),topicFamily=topicChinese?'"D360Chinese", "Microsoft YaHei", sans-serif':'"D360Bold", Arial, sans-serif',topicWeight=topicChinese?400:700;while(ts>30){ctx.font=`${topicWeight} ${ts}px ${topicFamily}`;if(ctx.measureText(s.topic||'________________').width<1020)break;ts-=2;}ctx.fillText(s.topic||'',23,112);const tw=s.topic?ctx.measureText(s.topic).width:220;ctx.fillRect(23,188,Math.max(100,tw),3);
const cw=G.w/s.cols,ch=G.h/s.rows;for(let i=0;i<s.cells.length;i++){const c=s.cells[i],x=G.x+i%s.cols*cw,y=G.y+Math.floor(i/s.cols)*ch;ctx.save();ctx.beginPath();ctx.rect(x,y,cw,ch);ctx.clip();ctx.fillStyle=c.bg;ctx.fillRect(x,y,cw,ch);if(c.type==='image'||c.type==='slice'){const src=assets[c.asset];if(src){ctx.filter=s.gray?'grayscale(1)':'none';cover(ctx,img(src),x,y,cw,ch,c.zoom,c.px,c.py,c.rect);ctx.filter='none';}}else{ctx.fillStyle=c.fg;textLines(ctx,c.text,x,y,cw,ch,c.type,c.size,c.type==='number'?'center':c.align);}ctx.restore();}
let visual=s.cells.some(c=>c.type==='image'||c.type==='slice'||c.bg!=='#f8f8f8');ctx.strokeStyle=s.line==='auto'?(visual?'#fff':'#000'):s.line;ctx.lineWidth=s.lineWidth;ctx.beginPath();for(let c=1;c<s.cols;c++){ctx.moveTo(G.x+c*cw,G.y);ctx.lineTo(G.x+c*cw,G.y+G.h);}for(let r=1;r<s.rows;r++){ctx.moveTo(G.x,G.y+r*ch);ctx.lineTo(G.x+G.w,G.y+r*ch);}ctx.stroke();for(const i of marks||[]){if(i>=0&&i<s.cells.length)check(ctx,G.x+i%s.cols*cw+2,G.y+Math.floor(i/s.cols)*ch+2,Math.min(cw,ch)*.265,s.lineWidth);}
const foot=img(REF.poster);if(foot.complete&&foot.naturalWidth)ctx.drawImage(foot,0,1509,1165,206,22,1513,1116,198);else{ctx.fillStyle='#000';ctx.font='700 64px Arial';ctx.fillText('360 Design Festival',23,1518);ctx.fillText('2026.11.26–11.29',23,1590);}}
function draw(){const c=$('poster'),ctx=c.getContext('2d');const s=stage==='entry'?entryState():state;drawTo(ctx,s,stage==='entry'?entryPicks:stage==='answer'||stage==='result'?picks:step===4&&state.mode==='exact'?new Set(state.answer):new Set());}
function hits(){const s=stage==='entry'?entryState():state;const h=$('hotspots');h.replaceChildren();s.cells.forEach((c,i)=>{const b=document.createElement('button');b.className='cell-hit';b.style.cssText=`left:${(G.x+i%s.cols*G.w/s.cols)/W*100}%;top:${(G.y+Math.floor(i/s.cols)*G.h/s.rows)/H*100}%;width:${G.w/s.cols/W*100}%;height:${G.h/s.rows/H*100}%`;b.setAttribute('aria-label',`第${i+1}格：${c.type==='image'||c.type==='slice'?'图片':c.text||'色块或空白'}`);b.addEventListener('click',()=>cellClick(i));h.append(b);});}
function cellClick(i){if(stage==='entry'){entryPicks.has(i)?entryPicks.delete(i):entryPicks.add(i);$('initialCount').innerHTML=`${entryPicks.size} <span>/ 3</span>`;$('initialConfirm').disabled=entryPicks.size!==3;draw();}}
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const on=(id,fn,event='click')=>{const el=$(id);if(el)el.addEventListener(event,fn);};
const topics=['design','humans','objects','words','images','art','beauty','value','meaning','emotion','memory','truth','freedom','life','love','lucky number'];
function textLines(ctx,t,x,y,w,h,kind,size=1,align='left'){
  const chinese=/[\u3400-\u9fff]/.test(t), advance=chinese?1.02:.83;
  let fs=(kind==='number'?Math.min(h*.32,w*.5):Math.min(w*.57,h*.56))*size;
  function wrap(f){ctx.font=`${kind==='number'||chinese?700:600} ${f}px Arial, "Microsoft YaHei", sans-serif`;const lines=[];for(const p of String(t).split('\n')){let l='';for(const ch of p){if(l&&ctx.measureText(l+ch).width>w-12){lines.push(l);l=ch;}else l+=ch;}lines.push(l);}return lines;}
  let lines=wrap(fs);const contentHeight=()=>{const m=ctx.measureText(lines.join('')||'H');return (lines.length-1)*fs*advance+(m.actualBoundingBoxAscent||fs*.75)+(m.actualBoundingBoxDescent||0);};while(fs>12&&(contentHeight()>h-16||lines.some(l=>ctx.measureText(l).width>w-12))){fs*=.96;lines=wrap(fs);}
  ctx.textAlign=kind==='number'||align==='center'?'center':'left';ctx.textBaseline='alphabetic';
  const metrics=ctx.measureText(lines.join('')||'H'),ascent=metrics.actualBoundingBoxAscent||fs*.75,descent=metrics.actualBoundingBoxDescent||0;
  let yy=kind==='number'?y+h/2+(ascent-descent)/2:y+8+ascent;
  for(const l of lines){ctx.fillText(l,ctx.textAlign==='center'?x+w/2:x+5,yy);yy+=fs*advance;}
}
const colors=['#f8f8f8','#000000','#ff0000','#00ae00','#1000ff','#ffdb00','#fa7eb8','#85bcda','#ec4328','#5939c6','#afbc69','#d5c4a5','#49685b','#8c252d','#dfdfdf','#334bac'];
let editTab='text',draft=null,lastSavedBundle='',shareCache=null,entryErrors=0,previousStage=null,suppressSave=false;
function checkpoint(){historyStack.push(clone(state));if(historyStack.length>30)historyStack.shift();redoStack=[];}
function commit(fn,repaint=true){checkpoint();fn();if(step<4)state.answer=[];shareCache=null;draw();hits();scheduleSave();if(repaint)renderPanel();}
function undo(){if(!historyStack.length)return;redoStack.push(clone(state));state=historyStack.pop();selected=Math.min(selected,state.cells.length-1);shareCache=null;render();scheduleSave();}
function redo(){if(!redoStack.length)return;historyStack.push(clone(state));state=redoStack.pop();selected=Math.min(selected,state.cells.length-1);shareCache=null;render();scheduleSave();}
function scheduleSave(){if(isGuest||stage==='entry'||suppressSave)return;clearTimeout(saveTimer);$('saveState').textContent='正在保存草稿…';saveTimer=setTimeout(saveDraft,500);}
function bundle(includeShelf=true){const s=clone(state);if(!includeShelf)s.shelf=[];const used=new Set([...s.cells,...s.shelf].map(c=>c.asset).filter(Boolean));if(s.whole)used.add(s.whole.asset);return {state:s,assets:Object.fromEntries([...used].map(k=>[k,assets[k]]).filter(x=>x[1]))};}
function db(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('no indexeddb'));const r=indexedDB.open('design360-select-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('drafts');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function saveDraft(){const data=bundle();try{const d=await db();await new Promise((res,rej)=>{const t=d.transaction('drafts','readwrite');t.objectStore('drafts').put(data,'current');t.oncomplete=res;t.onerror=()=>rej(t.error);});d.close();$('saveState').textContent='草稿已保存在此设备';}catch{try{localStorage.setItem('design360-draft',JSON.stringify(data));$('saveState').textContent='草稿已保存在此设备';}catch{$('saveState').textContent='草稿未能保存，请下载项目文件';}}}
async function loadDraft(){try{const d=await db();const v=await new Promise((res,rej)=>{const r=d.transaction('drafts').objectStore('drafts').get('current');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});d.close();if(v)return v;}catch{}try{return JSON.parse(localStorage.getItem('design360-draft')||'null');}catch{return null;}}
function modal(html){$('dialogBody').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();}
function confirmAction(title,text,fn){modal(`<h2>${title}</h2><p class="lead">${text}</p><div class="twocol"><button id="cancelModal">取消</button><button class="primary" id="confirmModal">确认</button></div>`);on('cancelModal',()=>$('dialog').close());on('confirmModal',()=>{$('dialog').close();fn();});}
