async function bootPolished(){await bootRefined();const refreshFonts=()=>Promise.allSettled([document.fonts.load('72px "D360Bold"'),document.fonts.load('72px "D360Medium"'),document.fonts.load('72px "D360Roman"'),document.fonts.load('72px "D360Chinese"')]).then(()=>render());if('requestIdleCallback'in window)requestIdleCallback(refreshFonts,{timeout:2500});else setTimeout(refreshFonts,0);$('dialog').addEventListener('close',()=>$('dialog').classList.remove('compact-palette'));matchMedia('(min-width:721px)').addEventListener('change',completionControl);$('helpBtn').onclick=()=>modal('<h2 class="help-title">Design 360 Festival</h2><p class="lead help-copy">自定义海报文案和网格形式，<br>自由设置网格大小、文字、图片和颜色。</p><p class="lead help-copy">操作步骤：<br>1. 点击标题下方的横线，选择海报文案。<br>2. 点击右上角数字，设置网格大小。<br>3. 轻点格子填充内容；长按并拖动格子，自由调整排列。</p>');render();}

// 1.5: the creator answers before exporting; guests start with empty picks.
let confirmedPosterSignature='',resultActionsShown=false;
function posterSignature(){const {answer,mode,palette,shelf,...poster}=state;return JSON.stringify(poster);}
finishPoster=function(){finishInline();if(!completeGrid()){toast('请先填充所有格子。');return;}if(!state.topic.trim()){toast('请填写提示词。');return;}picks=new Set(confirmedPosterSignature===posterSignature()?state.answer:[]);editorOpen=false;posterMenu=null;stage='answer';render();};
const goV14=go;go=function(n){if(n===4&&!isGuest)return finishPoster();return goV14(n);};
const submitV14=submitAnswer;submitAnswer=function(){if(!picks.size)return;if(isGuest)return submitV14();state.answer=[...picks].sort((a,b)=>a-b);confirmedPosterSignature=posterSignature();shareCache=null;stage='result';scheduleSave();render();};
startAnswer=function(){if(isGuest){picks.clear();stage='answer';render();}else finishPoster();};
shareSettings=function(){if(!isGuest&&(stage!=='result'||confirmedPosterSignature!==posterSignature()||!state.answer.length)){toast('请先作答并确认选择。');return;}modal(`<h2>邀请答题</h2><label class="field"><span>答案方式</span><select id="answerMode"><option value="open" ${state.mode==='open'?'selected':''}>自由选择</option><option value="exact" ${state.mode==='exact'?'selected':''}>以我的选择为标准答案</option></select></label><p class="small">朋友打开题目后，从未勾选的画面开始作答。</p><div class="stack"><button class="primary" id="publish">生成题目链接</button><button id="portableQuestion">下载题目 HTML</button></div>`);on('answerMode',e=>{state.mode=e.target.value;shareCache=null;scheduleSave();},'change');on('publish',publishQuestion);on('portableQuestion',portableQuestion);};
const panelV14=renderPanel;renderPanel=function(){panelV14();if(stage==='answer'){resultActionsShown=false;$('panel').innerHTML=`<h1>作答一次</h1><p class="lead">选择让你想到「${esc(state.topic)}」的格子。</p><p class="small">${isGuest&&state.mode==='exact'?'找出所有符合题目的格子。':'至少选择一格，可以选择多格。'}</p><p class="small">已选择 ${picks.size} / ${state.cells.length}</p><div class="tool-actions answer-actions"><button id="clearPicks">清空选择</button><button class="primary" id="submitAnswer" ${picks.size?'':'disabled'}>确认选择</button></div>`;on('clearPicks',()=>{picks.clear();render();});on('submitAnswer',submitAnswer);}else if(stage==='result'){const roleAction=isGuest?'<button id="copyCreate">我也来创作</button>':'<button id="inviteAnswer">邀请答题</button>';$('panel').innerHTML=`<div class="stack result-actions"><button class="primary" id="exportPNG">${phoneSaveMode()?'保存到相册':'保存海报'}</button>${roleAction}<button id="answerAgain">重新选择</button></div>`;on('exportPNG',()=>exportPNG(true));on('answerAgain',()=>{stage='answer';render();});on('inviteAnswer',shareSettings);on('copyCreate',startFresh);if(!resultActionsShown){resultActionsShown=true;requestAnimationFrame(()=>{if(matchMedia('(max-width:720px)').matches)$('panel').querySelector('.result-actions')?.scrollIntoView({block:'nearest',inline:'nearest'});});}}else resultActionsShown=false;updateDock();};
const dockV14=updateDock;updateDock=function(){dockV14();const d=$('mobileDock');if(stage==='result'){d.innerHTML=(isGuest?'':iconButton('dockBack','返回编辑','返回编辑'))+'<span class="dock-spacer"></span>'+iconButton('more','更多','更多');on('dockBack',()=>go(1));on('more',moreMenu);}else if(stage==='answer'){d.innerHTML=(isGuest?'':iconButton('dockBack','返回编辑','返回编辑'))+`<span class="dock-spacer">已选择 ${picks.size}</span><button class="primary" id="dockAnswer" ${picks.size?'':'disabled'}>确认选择</button>`;on('dockBack',()=>go(1));on('dockAnswer',submitAnswer);}};

function phoneSaveMode(){return matchMedia('(max-width:720px)').matches||navigator.maxTouchPoints>0;}
let savePreviewURL='';
function releaseSavePreview(){if(savePreviewURL){URL.revokeObjectURL(savePreviewURL);savePreviewURL='';}}
function openAlbumPreview(blob,name){releaseSavePreview();savePreviewURL=URL.createObjectURL(blob);const file=typeof File==='function'?new File([blob],name,{type:'image/png'}):null,canShare=!!file&&!!navigator.canShare&&navigator.canShare({files:[file]});modal(`<div class="save-poster"><h2>长按海报保存到相册</h2><p class="lead">长按下方海报，选择“保存图片”。</p><img id="albumPoster" src="${savePreviewURL}" alt="生成的海报，长按可保存"><p class="small">如果没有出现“保存图片”，请点击图片右上角菜单，再选择保存。</p>${canShare?'<button id="sharePosterFile">系统分享保存</button>':''}</div>`);const clean=()=>releaseSavePreview();$('dialog').addEventListener('close',clean,{once:true});on('sharePosterFile',async()=>{try{await navigator.share({title:'Design 360 Festival',files:[file]});}catch(e){if(e.name!=='AbortError')toast('系统分享暂时不可用，请长按海报保存。');}});toast('长按海报，然后选择“保存图片”。');}
const exportPNGV15=exportPNG;exportPNG=async function(marks=true){if(!phoneSaveMode())return exportPNGV15(marks);try{const blob=await posterPNGBlob(marks);openAlbumPreview(blob,`Design360-${safeName(state.topic)}.png`);}catch{toast('图片尚未读取完成，请稍后重试。');}};

bootPolished();
